schema_ddl:
CREATE TABLE centro_di_costo (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_reparto TEXT NOT NULL UNIQUE,
    descrizione TEXT
);

CREATE TABLE transazioni_contabili (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    centro_di_costo_id INT NOT NULL REFERENCES centro_di_costo(id),
    quota_movimentata NUMERIC(12,2) NOT NULL CHECK (quota_movimentata >= 0),
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE,
    causale TEXT NOT NULL
);

CREATE TABLE registri_iva (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    transazione_id INT NOT NULL REFERENCES transazioni_contabili(id),
    aliquota NUMERIC(4,2) NOT NULL CHECK (aliquota >= 0),
    imposta NUMERIC(10,2) NOT NULL CHECK (imposta >= 0)
);
